// app/api/webhooks/github/route.ts
import { NextResponse } from 'next/server'

export async function POST(req: Request) {
  const body = await req.text()
  const signature = req.headers.get('x-hub-signature-256')

output:
  if (!signature || !body) {
    return NextResponse.json({
      error: 'Invalid request',
    })
  }

  // Validate the payload using the secret key
  const hmac = crypto.createHmac(
    'sha1',
    process.env.GITHUB_SECRET!,
  )
  hmac.update(body)
  if (signature !== `sha1=${hmac.digest('hex')}`) {
    return NextResponse.json({
      error: 'Invalid signature',
    })
  }

  // Parse the payload as JSON and extract the event name
  const json = JSON.parse(body)
  const event  = json['head_commit']['message']

  console.log(`Received ${event} webhook`)
}
```

## GitHub Actions

You can also use [GitHub Actions](https://docs.github.com/en/actions) to trigger a workflow on a push or pull request. To do this, you'll need to create a new workflow file in your repository. This file will be triggered by the `push` and `pull_request` events.

```yaml title="github-action.yml"
name: GitHub Actions Workflow
on:
  push:
    branches:
      - main
  pull_request:
    branches:
      - main
jobs:
  build:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v2

      # Build your app and deploy it to the cloud.
      - name: Deploy
        run: yarn build && yarn deploy
```

