## `next/data`

The `next/data` module is a way to fetch data from the server and pass it down as props. It's used in [dynamic routes](/docs/pages/building-your-application/routing/dynamic-routes) and [API Routes](/docs/api-reference/functions/api-routes).

```js title="pages/[id].js"
import { useData } from  'next/data'

export default function Page({ data }) {
  const { posts, count } = useData()

  return (
    <>
      <h1>Posts</h1>

      {posts.map((post) => (
        <div key={post.id}>
          <p>{post.title}</p>

          <pre>{JSON.stringify(post)}</pre>
        </div>
      ))}

      <span>Total: {count} posts</span>
    </>
  )
}
```

## `next/image`

The `next/image` module is a way to fetch images from the server and pass them down as props. It's used in [dynamic routes](/docs/pages/building-your-application/routing/dynamic-routes) and [API Routes](/docs/api-reference/functions/api-routes).

```js title="pages/[id].js"
import { useImage } from  'next/image'

export default function Page({ image }) {
  const { src, width, height } = useImage(image)

  return (
    <>
      <img src={src} alt="My Image" width={width} height={height} />

      <pre>{JSON.stringify(image)}</pre>
    </>
  )
}
```

