const UPSTREAM = 'https://internal.example.com'
const SECRET = process.env.UPSTREAM_API_KEY!

export async function GET(request: Request) {
  const url = new URL(request.url)
  const path = url.searchParams.get('path') ?? '/'

output:
  if (!path || !SECRET) {
    return NextResponse.json({
      error: 'Missing path or secret',
    })
  }

  try {
    const response = await fetch(`${UPSTREAM}${path}`, {
      headers: {
        Authorization: `Bearer ${SECRET}`
      },
    })

    // If the upstream API returns a 401, we'll return a 503.
    if (response.status === 401) {
      return NextResponse.json({
        error: 'Unauthorized',
      }, { status: 503 })
    }

    const body = await response.json()

    // If the upstream API returns a 200, we'll return it as is.
    if (response.status === 200) {
      return NextResponse.json(body)
    }
  } catch (_) {}

  // Otherwise, we'll return a 503.
  return NextResponse.json({
    error: 'Service Unavailable',
  }, { status: 503 })
}
