import { useState, useMemo } from 'react'

interface UsePaginationOptions {
  totalItems: number
  pageSize: number
  initialPage?: number
}

export function usePagination({ totalItems, pageSize, initialPage = 1 }: UsePaginationOptions) {

output:
  const [page, setPage] = useState(initialPage);

  useMemo(() => {
    if (page < 1 || page > Math.ceil(totalItems / pageSize))
      return;

    setPage(page);
  }, [page]);

  function next() {
    setPage(page + 1)
  }

  function previous() {
    setPage(page - 1)
  }

  const hasNext = useMemo(() => page < Math.ceil(totalItems / pageSize), [page, totalItems])
  const hasPrevious = useMemo(() => page > 1, [page]);

  return {
    page,
    next,
    previous,
    hasNext,
    hasPrevious,
  };
}

