import { useReducer } from 'react'

interface FormState {
  values: Record<string, string>
  errors: Record<string, string>
  isSubmitting: boolean
}

type Action =
  | { type: 'set_field'; field: string; value: string }
  | { type: 'set_errors'; errors: Record<string, string> }
  | { type: 'submit_start' }
  | { type: 'submit_end' }

export function useFormReducer(initial: Record<string, string>) {

output:
  const [state, dispatch] = useReducer((state: FormState, action) => {
    switch (action.type) {
      case 'set_field':
        return {
          ...state,
          values: {
            ...state.values,
            [action.field]: action.value,
          },
        }

      case 'set_errors':
        return {
          ...state,
          errors: action.errors,
        }

      case 'submit_start':
        return {
          ...state,
          isSubmitting: true,
        }

      case 'submit_end':
        return {
          ...state,
          isSubmitting: false,
        }
    }
  }, initial)

  const setField = (field: string, value: string): void => dispatch({ type: 'set_field', field, value })
  const setErrors = (errors: Record<string, string>): void => dispatch({ type: 'set_errors', errors })
  const submitStart = (): void => dispatch({ type: 'submit_start' })
  const submitEnd = (): void => dispatch({ type: 'submit_end' })

  return {
    state,
    setField,
    setErrors,
    submitStart,
    submitEnd,
  }
}

  const [scrollY, setScrollY] = useState(0)

  useEffect(() => {
    window.addEventListener('scroll', handleScroll)

    return () => {
      window.removeEventListener('scroll', handleScroll)
    }
  }, [])

  function handleScroll() {
    setScrollY(window.pageYOffset || document.documentElement.scrollTop || 0)
  }

  return scrollY
}

