    return NextResponse.next()
  }
  if (bucket.count >= RATE_LIMIT) {
    return new NextResponse('Too Many Requests', {
      status: 429,
      headers: { 'Retry-After': String(Math.ceil((bucket.expiresAt - now) / 1000)) },
    })
  }
  bucket.count++
  return NextResponse.next()
}

