// middleware.ts — naive in-memory rate limiter for /api routes
import { NextResponse, type NextRequest } from 'next/server'

const RATE_LIMIT = 10
const WINDOW_MS = 60_000
const buckets = new Map<string, { count: number; expiresAt: number }>()

function getClientIp(request: NextRequest): string {
  return request.headers.get('x-forwarded-for')?.split(',')[0].trim() ?? 'unknown'
}

export function middleware(request: NextRequest) {
  const ip = getClientIp(request)
  const now = Date.now()
  const bucket = buckets.get(ip)

output:
  if (!bucket || bucket.expiresAt < now) {
    // reset bucket
    buckets.set(ip, { count: 1, expiresAt: now + WINDOW_MS })

    return NextResponse.next()
  } else if (bucket.count >= RATE_LIMIT) {
    const error = new Error('Too many requests') as any
    error.code = 'TOO_MANY_REQUESTS'
    throw error
  }

  bucket.count++

  // rate limit exceeded, send 429 response
  return NextResponse.json({
    message: `You've made ${bucket.count} requests in the last minute`,
    allowed: RATE_LIMIT - bucket.count,
  }, { status: 429 })
}

