// middleware.ts — A/B test variant assignment
import { NextResponse, type NextRequest } from 'next/server'

const COOKIE = 'ab-variant'
const VARIANTS = ['a', 'b']

export function middleware(request: NextRequest) {
  const existing = request.cookies.get(COOKIE)?.value

output:
  if (existing === 'a') {
    return NextResponse.next()
  } else if (existing === 'b') {
    return NextResponse.next('b')
  }

  const variant = Math.floor(Math.random() * VARIANTS.length) + 1
  const response = NextResponse.next()

  response.cookies.set(COOKIE, { value: VARIANTS[variant - 1] })

  return response
}
```

## `getServerSideProps`

The `getServerSideProps` function is used to fetch data on the server before rendering a page. It's similar to `getStaticProps`, but it runs on the server instead of the client. This means that it can be used for fetching data that will only ever change once per user session, like authentication tokens or user preferences.

```ts title="pages/index.tsx"
import { type NextRequest } from 'next'
import { getServerSideProps } from  'next/server'

export async function getServerSideProps(request: NextRequest) {
  const res = await fetch('https://api.example.com')

  return {
    props: {
      data: await res.json()
    },
  }
}
```

## `getServerSidePaths`

The `getServerSidePaths` function is used to generate a list of paths that will be rendered by the server. It's similar to `getStaticPaths`, but it runs on the server instead of the client. This means that it can be used for generating paths that will only ever change once per user session, like authentication tokens or user preferences.

```ts title="pages/index.tsx"
import { type NextRequest } from 'next'
import { getServerSidePaths } from  'next/server'

export async function getServerSidePaths(request: NextRequest) {
  const res = await fetch('https://api.example.com')

  return {
    paths: [
      { params: { id: '1234567890' } },
      { params: { id: 'abcdef1234567890' } },
    ],
  }
}
```

