    left: 0,
    right: 0,
    bottom: 0,
    backgroundColor: '#0000008c'
  }

  return (
    <div
      style={modalStyle}
      onClick={handleClick}>

      {isOpen &&
        <>
          <div
            className="modal-overlay"
            onClick={onClose}/>

          <div
            className="modal">

            {children}

          </div>

        </>
      }

    </div>
  )
