## `useField`

The `useField` hook returns a [field object](#field-object) that contains the current value, error and touched status of the field. It also provides a function to update the value of the field.

```tsx
import { useField } from 'react-dom'

export function Input({ name }: { name: string })  {
  const [value] = useField(name)

  return (
    <input
      type="text"
      value={value}
      onChange={(e) => {
        setValue(e.target.value)
      }}
    />
  )
}
```

## `useForm`

The `useForm` hook returns a [form object](#form-object). It also provides a function to update the form values and reset them back to their initial state.

```tsx
import { useForm } from 'react-dom'

export function Form()  {
  const {
    values,
    setValue,
    resetValues,
  } = useForm({
    firstName: '',
    lastName: ''
  })

  return (
    <form>
      <input
        type="text"
        name="firstName"
        value={values.firstName}
        onChange={(e) => {
          setValue(e.target.name, e.target.value)
        }}
      />

      <input
        type="text"
        name="lastName"
        value={values.lastName}
        onChange={(e) => {
          setValue(e.target.name, e.target.value)
        }}
      />
    </form>
  )
}
```

