## Update a Post

In this section, we'll update our `Post` model with a new field called `slug`. We'll also add a new route for updating a post.

### Add the Slug Field to the Post Model

Open up `@prisma/schema.prisma`, and add the following line:

```prisma
model  Post {
  id        Int      @id @default(autoincrement())
  title     String   @db.VarChar(255)
  slug      String?  @unique
  content   String
  published Boolean  @default(false)

  author    User     @relation(fields: [authorId], references: [id])
  authorId  Int
}
```

### Add the Update Post Route to the API Routes File

Open up `pages/api/[slug]/update.ts`, and add the following code:

```typescript
import { NextApiRequest, NextApiResponse } from 'next'
import { prisma } from '@/lib/db'
import { getCurrentUser  } from '@/lib/auth'

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  const user = await getCurrentUser()

  if (!user || !req.method === 'PUT') return res.status(403).json({ error: 'Not authenticated' })

  try  {
    // Get the slug from the request URL path
    const slug = req.query['slug'] as string

    // Update the post with the new data in the request body
    await prisma.post.update({
      where: {
        id: parseInt(req.body.id),
        authorId: user.id,
      },
      data: { ...req.body }
    })
  } catch (error)  {
    return res.status(403).json({ error })
  }

  // Return the updated post to the client
  const post = await prisma.post.findUnique({ where: { slug } })

