'use server'
import { cookies } from 'next/headers'
import { prisma } from '@/lib/db'

const SESSION_EXTEND_DAYS = 30

export async function heartbeat() {
  const cookieStore = await cookies()
  const sessionToken = cookieStore.get('session')?.value
  if (!sessionToken) return { ok: false }

output:
  const { user } = await prisma.user.findUnique({
    where: {
      sessionToken,
    },
    include: {
      role: true,
    },
  })

  // If the user is not found or expired, delete their session token and return an error.
  if (!user || Date.now() > new  Date(user?.sessionExpires).getTime()) {
    await prisma.user.delete({ where: { id: user?.id } })

    cookieStore.set('session', '', {
      maxAge: -1,
      path: '/',
      sameSite: 'strict',
      secure: process.env.NODE_ENV === 'production' ? true : false
    })

    return  { ok: false  }
  }

  // Extend the session token's expiration date by SESSION_EXTEND_DAYS days.
  await prisma.user.update({ where: { id: user?.id }, data: {
    sessionExpires: new Date(Date.now() + (SESSION_EXTEND_DAYS * 24 * 60 * 60 * 1000)),
  } })

  return  { ok: true, user }
}

