context.prefix:
'use client'
import { useState, useEffect } from 'react'

interface Command {
  id: string
  label: string
  shortcut?: string
  onSelect: () => void
}

export default function CommandPalette({ commands }: { commands: Command[] }) {

output:
  const [command, setCommand] = useState<string | null>(null)

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent): void => {
      if (!command && event.key === 'Escape') {
        setCommand(null)
      } else if (event.key === 'Enter' || event.key === ' ') {
        commands
          .filter(({ id }) => id === command)[0]
          ?.onSelect()

        setCommand(null)
      }
    }

    window.addEventListener('keydown', handleKeyDown, false)

    return () => {
      window.removeEventListener('keydown', handleKeyDown, false)
    }
  }, [command])

  const onInputChange = (event: React.ChangeEvent<HTMLInputElement>): void => {
    setCommand(event.target.value || null)
  }

  return  <>
    <input type="text" value={ command ?? ''} onChange={onInputChange}/>

    { commands
      .filter(({ id }) => !command || id === command)
      .map(({ label, shortcut }, index): ReactElement => (
        <button key={index}>
          { label }

          { shortcut &&  <>
            <span> ({shortcut})</span>
          </> }

        </button>
      ))}
  </>
}

